import{_ as d,W as i,s as o,u as l,ah as c,I as p,w as a,Z as n,A as t}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const C=JSON.parse('{"title":"expand 与 unexpand 命令实例教程 | LCTT x X-CMD","titleTemplate":false,"description":"expand 与 unexpand 命令实例教程 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"expand 与 unexpand 命令实例教程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"expand 与 unexpand 命令实例教程 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190610 Expand And Unexpand Commands Tutorial With Examples","title":"expand 与 unexpand 命令实例教程","tag":"201906"},"relativePath":"201906/20190610 Expand And Unexpand Commands Tutorial With Examples.md","filePath":"[post].md"}'),u={name:"201906/20190610 Expand And Unexpand Commands Tutorial With Examples.md"};function h(x,e,g,r,b,v){const s=i("Link");return l(),o("div",null,[e[15]||(e[15]=c('<h1 id="expand-与-unexpand-命令实例教程" tabindex="-1">expand 与 unexpand 命令实例教程 <a class="header-anchor" href="#expand-与-unexpand-命令实例教程" aria-label="Permalink to expand 与 unexpand 命令实例教程">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/05/Expand-And-Unexpand-Commands-720x340.png" alt="Expand And Unexpand Commands Explained"></p><p>本指南通过实际的例子解释两个 Linux 命令，即 <code>expand</code> 和 <code>unexpand</code>。对于好奇的人，<code>expand</code> 和 <code>unexpand</code> 命令用于将文件中的 <code>TAB</code> 字符替换为空格，反之亦然。在 MS-DOS 中也有一个名为 <code>expand</code> 的命令，它用于解压压缩文件。但 Linux 的 <code>expand</code> 命令只是将 <code>TAB</code> 转换为空格。这两个命令是 GNU coreutils 包的一部分，由 David MacKenzie 编写。</p><p>为了演示，我将在本文使用名为 <code>ostechnix.txt</code> 的文本文件。下面给出的所有命令都在 Arch Linux 中进行测试。</p><h3 id="expand-命令示例" tabindex="-1">expand 命令示例 <a class="header-anchor" href="#expand-命令示例" aria-label="Permalink to expand 命令示例">​</a></h3><p>与我之前提到的一样，<code>expand</code> 命令使用空格替换文件中的 <code>TAB</code> 字符。</p><p>现在，让我们将 <code>ostechnix.txt</code> 中的 <code>TAB</code> 转换为空格，并将结果写入标准输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand ostechnix.txt</span></span></code></pre></div><p>如果你不想在标准输出中显示结果，只需将其写入另一个文件，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand ostechnix.txt&gt;output.txt</span></span></code></pre></div><p>我们还可以将标准输入中的 <code>TAB</code> 转换为空格。为此，只需运行 <code>expand</code> 命令而不带文件名：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand</span></span></code></pre></div><p>只需输入文本并按回车键就能将 <code>TAB</code> 转换为空格。按 <code>CTRL+C</code> 退出。</p><p>如果你不想转换非空白字符后的 <code>TAB</code>，请使用 <code>-i</code> 标记，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand -i ostechnix.txt</span></span></code></pre></div><p>我们还可以设置每个 <code>TAB</code> 为指定数字的宽度，而不是 <code>8</code>（默认值）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand -t=5 ostechnix.txt</span></span></code></pre></div><p>我们甚至可以使用逗号分隔指定多个 <code>TAB</code> 位置，如下所示。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand -t 5,10,15 ostechnix.txt</span></span></code></pre></div><p>或者，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ expand -t &quot;5 10 15&quot; ostechnix.txt</span></span></code></pre></div><p>有关更多详细信息，请参阅手册页。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ man expand</span></span></code></pre></div><h3 id="unexpand-命令示例" tabindex="-1">unexpand 命令示例 <a class="header-anchor" href="#unexpand-命令示例" aria-label="Permalink to unexpand 命令示例">​</a></h3><p>正如你可能已经猜到的那样，<code>unexpand</code> 命令将执行与 <code>expand</code> 命令相反的操作。即它会将空格转换为 <code>TAB</code>。让我向你展示一些例子，以了解如何使用 <code>unexpand</code> 命令。</p><p>要将文件中的空白（当然是空格）转换为 <code>TAB</code> 并将输出写入标准输出，请执行以下操作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand ostechnix.txt</span></span></code></pre></div><p>如果要将输出写入文件而不是仅将其显示到标准输出，请使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand ostechnix.txt&gt;output.txt</span></span></code></pre></div><p>从标准输出读取内容，将空格转换为制表符：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand</span></span></code></pre></div><p>默认情况下，<code>unexpand</code> 命令仅转换初始的空格。如果你想转换所有空格而不是只是一行开头的空格，请使用 <code>-a</code> 标志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand -a ostechnix.txt</span></span></code></pre></div><p>仅转换一行开头的空格（请注意它会覆盖 <code>-a</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand --first-only ostechnix.txt</span></span></code></pre></div><p>使多少个空格替换成一个 <code>TAB</code>，而不是 <code>8</code>（会启用 <code>-a</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand -t 5 ostechnix.txt</span></span></code></pre></div><p>相似地，我们可以使用逗号分隔指定多个 <code>TAB</code> 的位置。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand -t 5,10,15 ostechnix.txt</span></span></code></pre></div><p>或者，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ unexpand -t &quot;5 10 15&quot; ostechnix.txt</span></span></code></pre></div><p>有关更多详细信息，请参阅手册页。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ man unexpand</span></span></code></pre></div><p>在处理大量文件时，<code>expand</code> 和 <code>unexpand</code> 命令对于用空格替换不需要的 <code>TAB</code> 时非常有用，反之亦然。</p><hr>',45)),p("p",null,[e[1]||(e[1]=a("via: ")),n(s,{href:"https://www.ostechnix.com/expand-and-unexpand-commands-tutorial-with-examples/"},{default:t(()=>e[0]||(e[0]=[a("https://www.ostechnix.com/expand-and-unexpand-commands-tutorial-with-examples/")])),_:1})]),p("p",null,[e[6]||(e[6]=a("作者：")),n(s,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>e[2]||(e[2]=[a("sk")])),_:1}),e[7]||(e[7]=a(" 选题：")),n(s,{href:"https://github.com/lujun9972"},{default:t(()=>e[3]||(e[3]=[a("lujun9972")])),_:1}),e[8]||(e[8]=a(" 译者：")),n(s,{href:"https://github.com/geekpi"},{default:t(()=>e[4]||(e[4]=[a("geekpi")])),_:1}),e[9]||(e[9]=a(" 校对：")),n(s,{href:"https://github.com/wxy"},{default:t(()=>e[5]||(e[5]=[a("wxy")])),_:1})]),p("p",null,[e[12]||(e[12]=a("本文由 ")),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>e[10]||(e[10]=[a("LCTT")])),_:1}),e[13]||(e[13]=a(" 原创编译，")),n(s,{href:"https://linux.cn/"},{default:t(()=>e[11]||(e[11]=[a("Linux中国")])),_:1}),e[14]||(e[14]=a(" 荣誉推出"))])])}const T=d(u,[["render",h]]);export{C as __pageData,T as default};
